// Regenerates packages/db-types/src/database.ts from the linked Supabase project.
import { execSync } from 'node:child_process';
import { writeFileSync } from 'node:fs';

const types = execSync('supabase gen types typescript --linked --schema public,api', { encoding: 'utf8' });
writeFileSync(
  'packages/db-types/src/database.ts',
  '// Generated by `pnpm db:types` (supabase gen types). Never edit by hand.\n' + types,
);
console.log('packages/db-types/src/database.ts updated');
